var logger = require('./logger');
var redis = require("redis");
var client;
if (process.env.REDIS_PORT_6379_TCP_ADDR && process.env.REDIS_PORT_6379_TCP_PORT && process.env.REDIS_PASSWORD) {
    client = redis.createClient({
        host: process.env.REDIS_PORT_6379_TCP_ADDR,
        port: process.env.REDIS_PORT_6379_TCP_PORT,
        password: [REDACTED]
    });
}
else {
    client = redis.createClient();
}


client.on("error", function (err) {
    logger.error('Redis Error ' + err);
});

module.exports = {
    set: function (key, value) {
        client.set(key, value, redis.print);
        client.expire(key, 300);
        logger.info('Set redis: ' + key);
    },
    client: client
};

var express = require('express');
var session = require('express-session');

var logger = require('./tools/logger');
var passport = require('./tools/passport');
var config = require('./config');

logger.info(`🍻 gugu start! Cheers!`);

var app = express();

app.use(session({
    secret: 'keyboard cat',
    resave: false,
    saveUninitialized: true,
}));
app.use(passport.initialize());
app.use(passport.session());

app.all('*', require('./routes/all'));

app.get('/login',
    passport.authenticate('weibo'),
    function (req, res) {
    }
);

app.get('/callback',
    passport.authenticate('weibo', { failureRedirect: '/login' }),
    function (req, res) {
        res.send('<script>window.location.href = "' + config.redirectURL + '"</script>');
    }
);

app.get('/logout', function (req, res) {
    req.logout();
    res.send('<script>window.location.href = "' + config.redirectURL + '"</script>');
});

app.get('/account', function (req, res) {
    res.send(JSON.stringify(req.user));
});

app.post('/print', require('./routes/print'));
app.get('/status', require('./routes/status'));

app.listen(1211);

var passport = require('passport');
var WeiboStrategy = require('passport-weibo').Strategy;
var config = require('../config');

passport.serializeUser(function (user, done) {
    done(null, user);
});

passport.deserializeUser(function (obj, done) {
    done(null, obj);
});

passport.use(new WeiboStrategy({
    clientID: config.appKey,
    clientSecret: [REDACTED],
    callbackURL: config.URL + '/callback'
},
    function (accessToken, refreshToken, profile, done) {
        process.nextTick(function () {
            return done(null, profile);
        });
    }
));

module.exports = passport;

var Memobird = require('memobird');
var config = require('../config');

var gugu = new Memobird({
    ak: config.ak,
    memobirdID: config.memobirdID,
    useridentifying: config.useridentifying,
});

gugu.init();

module.exports = gugu;

var log4js = require('log4js');
log4js.configure({
    appenders: [
        {
            type: "file",
            filename: 'logs/gugu.log',
            maxLogSize: 20480,
            backups: 3,
            category: [ 'gugu','console' ]
        },
        {
            type: "console"
        }
    ],
    replaceConsole: true
});
var logger = log4js.getLogger('gugu');
logger.setLevel('INFO');

module.exports = logger;

var config = require('../config');

module.exports = function (req, res, next) {
    if (req.headers.origin) {
        for (var i = 0; i < config.allowOrigin.length; i++) {
            if (new RegExp(config.allowOrigin[i]).test(req.headers.origin)) {
                res.header("Access-Control-Allow-Origin", req.headers.origin);
                res.header('Access-Control-Allow-Credentials', 'true');
                res.header('Access-Control-Allow-Headers', 'Content-Type, Content-Length, Authorization, Accept, X-Requested-With , yourHeaderFeild');
                res.header('Access-Control-Allow-Methods', 'PUT, POST, GET, DELETE, OPTIONS');
                res.header('content-type', 'application/json; charset=utf-8');

                if (req.method == 'OPTIONS') {
                    res.send(200);
                }
                else {
                    next();
                    return;
                }
            }
        }
        res.send('Unallowed origin');
    }
    else {
        if (req.method == 'OPTIONS') {
            res.send(200);
        }
        else {
            next();
        }
    }
};

var fs = require('fs');
var url = require('url');
var logger = require('../tools/logger');
var gugu = require('../tools/gugu');
var config = require('../config');

var reqIP = {};
var reqUser = {};

module.exports = function (req, res) {
    var body = '';
    var jsonStr = {};

    var ip = req.headers['x-forwarded-for'] ||
        req.connection.remoteAddress ||
        req.socket.remoteAddress ||
        req.connection.socket.remoteAddress;

    req.on('data', dataListener);
    req.on('end', endListener);

    function dataListener (chunk) {
        body += chunk;
    }
    function endListener () {
        cleanListener();
        var type;
        var content;
        try {
            jsonStr = JSON.parse(body);
            type = jsonStr.type;
            content = jsonStr.content;
        } catch (err) {
            jsonStr = {};
        }

        if (!req.user) {
            logger.info(`Reject gugu print for not login, IP: ${ip}`);
            res.send(`{"code": 4, "msg": " 请先登录"}`);
            return;
        }

        // check black ip
        var blanklist = fs.readFileSync('blacklist').toString().split('\n');
        if (blanklist.indexOf(ip.split(',')[0]) !== -1 || blanklist.indexOf(req.user.id) !== -1 || blanklist.indexOf(req.user.displayName) !== -1) {
            logger.info(`Reject gugu print for black ip, IP: ${ip}`);
            res.send(`{"code": 1, "msg": "抱歉，您已被加入黑名单"}`);
            return;
        }

        if (content.length > config.maxLength) {
            logger.info(`Reject gugu print for max length, IP: ${ip}`);
            res.send(`{"code": 2, "msg": "超出最大文本长度"}`);
            return;
        }

        // frequency limitation(ip)
        if (reqIP[ip] && reqIP[ip] >= config.frequency) {
            logger.info(`Reject gugu print for frequent operation, IP: ${ip}`);
            res.send(`{"code": 3, "msg": "操作频繁，频繁次数过多会被拉入黑名单哦"}`);
            return;
        }
        else {
            if (reqIP[ip]) {
                reqIP[ip]++;
            }
            else {
                reqIP[ip] = 1;
            }
            setTimeout(function () {
                reqIP[ip]--;
            }, 1800000);   // 30 min
        }

        // frequency limitation(weibo user)
        var userid = req.user.id;
        if (reqUser[userid] && reqUser[userid] >= config.frequency) {
            logger.info(`Reject gugu print for frequent operation, User: ${userid} ${req.user.displayName}`);
            res.send(`{"code": 3, "msg": "操作频繁，频繁次数过多会被拉入黑名单哦"}`);
            return;
        }
        else {
            if (reqUser[userid]) {
                reqUser[userid]++;
            }
            else {
                reqUser[userid] = 1;
            }
            setTimeout(function () {
                reqUser[userid]--;
            }, 1800000);   // 30 min
        }

        logger.info(`gugu print ${type} ${content}, IP: ${ip}`);

        switch (type) {
            case '1':
                gugu.printText(req.user.displayName + ': ' + content)
                    .then(printcontentid => res.send(`{"code": 0, "msg": "成功发送打印请求", "user": "${req.user.displayName}", "printcontentid": "${printcontentid}"}`));
                break;
            case '2':
                gugu.printImage(content)
                    .then(printcontentid => res.send(`{"code": 0, "msg": "成功发送打印请求", "user": "${req.user.displayName}", "printcontentid": "${printcontentid}"}`));
                break;
            default:
                res.send(`{"code": 1, "msg": "参数错误"}`);
        }
    }

    function cleanListener () {
        req.removeListener('data', dataListener);
        req.removeListener('end', endListener);
    }
};

var url = require('url');
var logger = require('../tools/logger');
var gugu = require('../tools/gugu');

module.exports = function (req, res) {

    var ip = req.headers['x-forwarded-for'] ||
        req.connection.remoteAddress ||
        req.socket.remoteAddress ||
        req.connection.socket.remoteAddress;

    var query = url.parse(req.url, true).query;
    var id = query.id;

    logger.info(`gugu status ${id}, IP: ${ip}`);

    gugu.watch(id, 1000, 20000)
        .then(printflag => res.send('' + printflag));
};
